"use client";

import {
  Plus,
  MessageSquare,
  History,
  Search,
  FolderKanban,
  GraduationCap,
  Monitor,
  PanelLeftClose,
  PanelLeftOpen,
  Sun,
  Moon,
} from "lucide-react";

import { useTheme } from "./ThemeProvider";

interface SidebarProps {
  isOpen: boolean;
  onToggle: () => void;
}

const menuItems = [
  {
    label: "Nova conversa",
    icon: Plus,
  },
  {
    label: "Chat",
    icon: MessageSquare,
  },
  {
    label: "API",
    icon: History,
  },
  {
    label: "Pesquisar",
    icon: Search,
  },
  {
    label: "Projetos",
    icon: FolderKanban,
  },
  {
    label: "Aprender",
    icon: GraduationCap,
  },
  {
    label: "Meu PC",
    icon: Monitor,
  },
];

export default function Sidebar({ isOpen, onToggle }: SidebarProps) {
  const { theme, toggleTheme } = useTheme();

  const isDark = theme === "dark";

  return (
    <aside
      className={`
        relative flex h-screen shrink-0 flex-col
        border-r
        border-[var(--sidebar-border)]
        bg-[var(--sidebar-background)]
        transition-all duration-300 ease-in-out
        ${isOpen ? "w-64" : "w-[72px]"}
      `}
    >
      {/* =====================================================
          HEADER
      ====================================================== */}

      <div
        className={`
          flex h-20 items-center
          border-b
          border-[var(--sidebar-border)]
          px-4
          ${isOpen ? "justify-between" : "justify-center"}
        `}
      >
        {/* LOGO */}

        <div
          className={`
            flex items-center gap-2
            overflow-hidden
            transition-all duration-300
            ${isOpen ? "w-auto opacity-100" : "w-0 opacity-0"}
          `}
        >
          <img
            src="/assets/LOGO.png"
            alt="SAITE"
            className="h-12 w-auto object-contain"
          />

          <img
            src="/assets/TITULO.png"
            alt="SAITE"
            className="h-25 w-auto object-contain"
          />
        </div>

        {/* SIDEBAR TOGGLE */}

        <button
          onClick={onToggle}
          aria-label={isOpen ? "Fechar menu" : "Abrir menu"}
          className="
            flex h-9 w-9 shrink-0
            items-center justify-center
            rounded-lg
            text-[var(--foreground-secondary)]
            transition-all duration-200
            hover:bg-[var(--sidebar-hover)]
            hover:text-[var(--foreground)]
          "
        >
          {isOpen ? (
            <PanelLeftClose size={19} strokeWidth={1.8} />
          ) : (
            <PanelLeftOpen size={19} strokeWidth={1.8} />
          )}
        </button>
      </div>

      {/* =====================================================
          MENU
      ====================================================== */}

      <nav
        className="
          flex flex-1 flex-col
          gap-1
          overflow-hidden
          px-3 py-5
        "
      >
        {menuItems.map((item) => {
          const Icon = item.icon;

          return (
            <button
              key={item.label}
              className={`
                group
                flex h-11
                items-center
                rounded-xl
                text-sm
                text-[var(--foreground-secondary)]
                transition-all duration-200
                hover:bg-[var(--sidebar-hover)]
                hover:text-[var(--foreground)]
                ${isOpen ? "gap-3 px-3" : "justify-center px-0"}
              `}
            >
              <Icon
                size={19}
                strokeWidth={1.8}
                className="
                  shrink-0
                  transition-transform
                  duration-200
                  group-hover:scale-105
                "
              />

              <span
                className={`
                  overflow-hidden
                  whitespace-nowrap
                  transition-all duration-200
                  ${isOpen ? "w-auto opacity-100" : "w-0 opacity-0"}
                `}
              >
                {item.label}
              </span>
            </button>
          );
        })}
      </nav>

      {/* =====================================================
          THEME TOGGLE
      ====================================================== */}

      <div
        className="
          border-t
          border-[var(--sidebar-border)]
          p-3
        "
      >
        <button
          onClick={toggleTheme}
          aria-label={
            isDark ? "Mudar para modo claro" : "Mudar para modo escuro"
          }
          className={`
            group
            flex h-11 w-full
            items-center
            rounded-xl
            text-sm
            text-[var(--foreground-secondary)]
            transition-all duration-200
            hover:bg-[var(--sidebar-hover)]
            hover:text-[var(--foreground)]
            ${isOpen ? "gap-3 px-3" : "justify-center px-0"}
          `}
        >
          {/* ÍCONE */}

          <span
            className="
              flex h-7 w-7
              shrink-0
              items-center justify-center
              rounded-lg
              bg-[var(--background-tertiary)]
              transition-all duration-300
            "
          >
            {isDark ? (
              <Moon size={16} strokeWidth={1.8} />
            ) : (
              <Sun size={16} strokeWidth={1.8} />
            )}
          </span>

          {/* TEXTO */}

          <span
            className={`
              overflow-hidden
              whitespace-nowrap
              transition-all duration-200
              ${isOpen ? "w-auto opacity-100" : "w-0 opacity-0"}
            `}
          >
            {isDark ? "Modo escuro" : "Modo claro"}
          </span>
        </button>
      </div>
    </aside>
  );
}
